// Code node "Find rising searches" - lists the searches really growing around your topics, best first.
const settings = $('Your settings').first().json;
const results = $input.all().map(i => i.json).filter(i => i.type === 'explore');
const maxCandidates = 20; // more than needed: searches already covered in previous weeks are skipped next
// Google News edition (country:language) used to find the articles explaining each trend.
const EDITIONS = { US: 'US:en', GB: 'GB:en', CA: 'CA:en', AU: 'AU:en', IN: 'IN:en', IE: 'IE:en', NZ: 'NZ:en', FR: 'FR:fr',
  DE: 'DE:de', ES: 'ES:es', IT: 'IT:it', PT: 'PT:pt-150', BR: 'BR:pt-419', MX: 'MX:es-419', NL: 'NL:nl', BE: 'BE:fr',
  CH: 'CH:de', AT: 'AT:de', PL: 'PL:pl', SE: 'SE:sv', JP: 'JP:ja', KR: 'KR:ko' };
const newsEdition = EDITIONS[String(settings.country || '').trim().toUpperCase()] || 'US:en';

// Google's "rising" lists can contain unrelated bot-like searches: keep the ones that really are about the topic,
// i.e. that share at least 2 of its words (1 for a one-word topic). "soup recipes" is not about "protein recipes".
const STOP = new Set(['for', 'the', 'and', 'with', 'how', 'what', 'near', 'from', 'your']);
const words = s => String(s).toLowerCase().split(/[^\p{L}\p{N}]+/u).filter(w => w.length >= 3 && !STOP.has(w));
const isAbout = (query, termWords) => {
  const shared = new Set(words(query).filter(w => termWords.has(w))).size;
  return shared >= Math.min(2, termWords.size);
};
const growthValue = g => (g === 'Breakout' ? 5000 : Number(g) || 0);

const topics = [];
const candidates = new Map();
for (const r of results) {
  const termWords = new Set(words(r.searchTerm));
  const related = q => isAbout(q.query, termWords);
  topics.push({
    topic: r.searchTerm,
    direction: r.summary ? r.summary.trendDirection : null,
    change: r.summary ? r.summary.changePercent : null,
  });
  for (const q of (r.relatedQueriesRising || []).filter(related)) {
    const key = q.query.toLowerCase();
    const growth = growthValue(q.growthPercent);
    if (!candidates.has(key) || candidates.get(key).growth < growth) {
      candidates.set(key, {
        query: q.query,
        topic: r.searchTerm,
        growth,
        growthLabel: q.growthPercent === 'Breakout' ? 'Breakout' : `+${q.growthPercent}%`,
        trendsUrl: q.link,
      });
    }
  }
}

let trends = [...candidates.values()].sort((a, b) => b.growth - a.growth).slice(0, maxCandidates);

// Quiet week: complete with the most searched queries of each topic (steady demand, lower priority),
// taking them in turn from every topic so that no topic takes all the places.
const topLists = results.map(r => {
  const termWords = new Set(words(r.searchTerm));
  return (r.relatedQueriesTop || []).slice(0, 10)
    .filter(q => q.query.toLowerCase() !== r.searchTerm.toLowerCase() && isAbout(q.query, termWords))
    .map(q => ({ query: q.query, topic: r.searchTerm, growth: 0, growthLabel: 'Top search', trendsUrl: q.link }));
});
for (let rank = 0; rank < 10 && trends.length < maxCandidates; rank++) {
  for (const list of topLists) {
    const q = list[rank];
    if (!q || trends.length >= maxCandidates || candidates.has(q.query.toLowerCase())) continue;
    candidates.set(q.query.toLowerCase(), true);
    trends.push(q);
  }
}

return trends.map(t => ({ json: { ...t, topics, newsEdition } }));

// Code node "Pick this week's searches" - keeps the best new searches, balanced across your topics and without
// near-duplicates ("6 month marathon training plan" vs "5 month marathon training plan"), grouped for the next steps.
const settings = $('Your settings').first().json;
const perWeek = Math.max(1, Math.min(10, Number(settings.ideasPerWeek) || 6));
const fresh = $input.all().map(i => i.json).filter(t => t.query);  // empty when everything was already covered

const STOP = new Set(['for', 'the', 'and', 'with', 'how', 'what', 'best', 'near']);
const words = s => new Set(String(s).toLowerCase().split(/[^\p{L}\p{N}]+/u).filter(w => w.length >= 1 && !STOP.has(w)));
// Compare only what distinguishes two searches from their topic: "6 month ... plan" vs "5 month ... plan" are the
// same idea, "chair yoga for beginners" and "yoga for beginners at home" are not.
const similar = (a, b) => {
  const topicWords = words(a.topic);
  const extra = q => new Set([...words(q.query)].filter(w => !topicWords.has(w) && !/^\d+$/.test(w)));
  const ea = extra(a), eb = extra(b);
  if (!ea.size || !eb.size) return ea.size === eb.size;
  const common = [...ea].filter(w => eb.has(w)).length;
  return common / Math.min(ea.size, eb.size) >= 0.75;
};

// One queue per topic (already sorted best first), then take from each topic in turn.
const queues = new Map();
for (const t of fresh) {
  if (!queues.has(t.topic)) queues.set(t.topic, []);
  queues.get(t.topic).push(t);
}
const picked = [];
while (picked.length < perWeek && [...queues.values()].some(q => q.length)) {
  for (const q of queues.values()) {
    while (q.length && picked.length < perWeek) {
      const t = q.shift();
      if (!picked.some(p => p.topic === t.topic && similar(p, t))) { picked.push(t); break; }
    }
  }
}

const trends = picked.map(({ topics, newsEdition, ...t }) => t);
const first = fresh[0] || {};
return [{ json: { hasTrends: trends.length > 0, trends, topics: first.topics || [], newsEdition: first.newsEdition || 'US:en' } }];

