// Code node "Score trends and build the AI brief" - adds the news explaining each trend, scores it and
// writes a compact, fact-only brief for the AI.
const settings = $('Your settings').first().json;
const { trends, topics } = $("Pick this week's searches").first().json;

// News articles found for each rising search (the news step may have failed: ideas are still written without them).
const articles = new Map();
for (const { json: a } of $input.all()) {
  if (!a || !a.input || !a.title) continue;
  const key = String(a.input).toLowerCase();
  if (!articles.has(key)) articles.set(key, []);
  articles.get(key).push({ title: a.title, source: a.source, url: a.url || a.googleNewsUrl, publishedAt: a.publishedAt });
}

// Priority from the data, not from the AI: search growth first, then press coverage and the topic's momentum.
const momentum = Object.fromEntries(topics.map(t => [t.topic, t.direction === 'up' ? 10 : t.direction === 'down' ? -10 : 0]));
const scored = trends.map(t => {
  const news = (articles.get(t.query.toLowerCase()) || []).slice(0, 3);
  const growthPoints = t.growthLabel === 'Breakout' ? 100 : t.growth ? Math.min(t.growth, 1000) / 10 : 5;
  const score = Math.round(growthPoints + news.length * 5 + (momentum[t.topic] || 0));
  return { ...t, news, score, priority: score >= 40 ? 'High' : score >= 20 ? 'Medium' : 'Low' };
}).sort((a, b) => b.score - a.score);
if (scored.length && !scored.some(t => t.priority === 'High') && scored[0].score >= 25) scored[0].priority = 'High';

const day = d => (d ? d.slice(0, 10) : '');
const lines = scored.map(t => {
  const press = t.news.length
    ? t.news.map(n => `  - "${n.title}" (${n.source}, ${day(n.publishedAt)})`).join('\n')
    : '  - no recent press coverage found';
  const growth = t.growthLabel === 'Top search' ? 'steady demand (one of the most searched queries for this topic)' : t.growthLabel;
  return `Search: "${t.query}" (topic: ${t.topic})\n- Search growth: ${growth}\n- Priority: ${t.priority}\n- Recent news:\n${press}`;
});
const topicLines = topics.map(t => `- ${t.topic}: ${t.direction || 'n/a'}, ${t.change ?? 'n/a'}% over the past 30 days`);

const brief = [
  `Audience: ${settings.audience || 'a general audience'}`,
  `Country: ${settings.country || 'worldwide'}`,
  `Write the ideas in: ${settings.language || 'English'}`,
  `Number of ideas: ${scored.length} (one per search)`,
  '',
  'Topic interest (Google Trends):',
  ...topicLines,
  '',
  'Rising searches, from highest to lowest priority:',
  ...lines,
].join('\n');

return [{ json: { brief, trends: scored } }];

// Code node "Prepare calendar rows" - joins each new idea with its search data and news sources.
const { trends } = $('Score trends and build the AI brief').first().json;
const find = q => trends.find(t => t.query.toLowerCase() === String(q || '').toLowerCase().trim());
const order = { High: 0, Medium: 1, Low: 2 };
const today = new Date().toISOString().slice(0, 10);

const rows = $input.all().map(({ json: idea }) => {
  const t = find(idea.targetSearch);
  const outline = Array.isArray(idea.outline) ? idea.outline : [];
  return {
    Date: today,
    Priority: t ? t.priority : 'Low',
    Title: idea.title,
    Format: idea.format,
    'Target search': idea.targetSearch,
    'Search growth': t ? t.growthLabel : '',
    'Why now': idea.whyNow,
    Outline: outline.map(o => `• ${o}`).join('\n'),
    Sources: t ? t.news.map(n => n.url).join('\n') : '',
    'Google Trends': t ? t.trendsUrl : '',
    Status: 'Idea',
  };
});

rows.sort((a, b) => order[a.Priority] - order[b.Priority]);
return rows.map(json => ({ json }));

// Code node "Design the email" - one email with every new idea, ranked by priority.
const settings = $('Your settings').first().json;
const { trends } = $('Score trends and build the AI brief').first().json;
const rows = $input.all().map(i => i.json);

const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const PRIORITY = {
  High: { bar: '#E5484D', bg: '#FDECEC', text: '#B42318', label: 'High priority' },
  Medium: { bar: '#F5A524', bg: '#FEF4E2', text: '#9A5B00', label: 'Medium priority' },
  Low: { bar: '#8E9AAF', bg: '#EEF1F6', text: '#4A5568', label: 'Low priority' },
};
// Publisher names can be long ("Bon Appétit: Recipes, Cooking, ... | Bon Appétit") or raw domains.
const outlet = s => { const t = String(s || '').replace(/^www\./, ''); const short = t.split(/ [|:–-] /)[0]; return short.length > 40 ? short.slice(0, 38) + '…' : short; };
const newsFor = q => (trends.find(t => t.query.toLowerCase() === String(q).toLowerCase()) || { news: [] }).news;
const articleCount = trends.reduce((n, t) => n + t.news.length, 0);
const highCount = rows.filter(r => r.Priority === 'High').length;
const dateLabel = new Date().toLocaleDateString('en-US', { day: 'numeric', month: 'long', year: 'numeric' });
const font = "font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif";

const stat = (value, label) => `<td align="center" style="padding:14px 6px;background:#F7F8FC;border-radius:10px">
  <div style="font-size:24px;font-weight:700;color:#1E1B4B">${value}</div>
  <div style="font-size:12px;color:#6B7280;margin-top:2px">${label}</div></td>`;

// A rising search gets a green arrow; a steadily popular one ("Top search") a neutral grey chip.
const growthChip = g => !g ? '' : g === 'Top search'
  ? `<span style="display:inline-block;margin-left:6px;padding:2px 8px;border-radius:6px;background:#F3F4F6;color:#4B5563;font-weight:700;font-size:12px">Steady demand</span>`
  : `<span style="display:inline-block;margin-left:6px;padding:2px 8px;border-radius:6px;background:#E7F8EF;color:#067647;font-weight:700;font-size:12px">&#9650; ${esc(g)}</span>`;

const card = (r, n) => {
  const p = PRIORITY[r.Priority] || PRIORITY.Low;
  const news = newsFor(r['Target search']).slice(0, 2).map(a =>
    `<div style="margin-top:6px;font-size:13px;line-height:1.5"><a href="${esc(a.url)}" style="color:#4338CA;text-decoration:none">${esc(a.title)}</a> <span style="color:#9CA3AF">· ${esc(outlet(a.source))}</span></div>`).join('');
  const outline = String(r.Outline || '').split('\n').filter(Boolean).map(o =>
    `<li style="margin:3px 0">${esc(o.replace(/^•\s*/, ''))}</li>`).join('');
  return `<tr><td style="padding:0 0 16px">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border:1px solid #E5E7EB;border-radius:12px;border-left:5px solid ${p.bar}">
  <tr><td style="padding:18px 20px">
    <span style="display:inline-block;padding:3px 10px;border-radius:999px;background:${p.bg};color:${p.text};font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.4px">${p.label}</span>
    <span style="display:inline-block;padding:3px 10px;border-radius:999px;background:#EEF2FF;color:#4338CA;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.4px;margin-left:4px">${esc(r.Format)}</span>
    <div style="font-size:18px;font-weight:700;color:#111827;line-height:1.35;margin:12px 0 8px">${n}. ${esc(r.Title)}</div>
    <div style="font-size:13px;color:#374151">Target search: <a href="${esc(r['Google Trends'])}" style="color:#111827;font-weight:600;text-decoration:none">${esc(r['Target search'])}</a>
      ${growthChip(r['Search growth'])}</div>
    <div style="font-size:14px;color:#374151;line-height:1.6;margin-top:10px"><strong style="color:#111827">Why now:</strong> ${esc(r['Why now'])}</div>
    ${news ? `<div style="margin-top:10px;padding:10px 12px;background:#F9FAFB;border-radius:8px"><div style="font-size:11px;font-weight:700;color:#6B7280;text-transform:uppercase;letter-spacing:.4px">In the news</div>${news}</div>` : ''}
    ${outline ? `<ul style="font-size:14px;color:#374151;line-height:1.5;margin:12px 0 0;padding-left:20px">${outline}</ul>` : ''}
  </td></tr></table></td></tr>`;
};

const html = `<div style="background:#F3F4F8;padding:24px 12px;${font}">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:640px;margin:0 auto;background:#FFFFFF;border-radius:16px;overflow:hidden">
<tr><td style="background:#1E1B4B;padding:28px 28px 24px">
  <div style="font-size:12px;font-weight:700;color:#A5B4FC;letter-spacing:1.5px;text-transform:uppercase">Weekly content radar</div>
  <div style="font-size:26px;font-weight:700;color:#FFFFFF;margin-top:6px;line-height:1.25">${rows.length} content idea${rows.length > 1 ? 's' : ''} people are starting to search for</div>
  <div style="font-size:14px;color:#C7D2FE;margin-top:8px">${esc(settings.country || 'Worldwide')} · ${esc(dateLabel)} · for ${esc(settings.audience || 'your audience')}</div>
</td></tr>
<tr><td style="padding:20px 28px 4px">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="6"><tr>
  ${stat(trends.length, 'rising searches')}${stat(articleCount, 'news articles read')}${stat(highCount, 'high priority')}
  </tr></table>
</td></tr>
<tr><td style="padding:16px 28px 4px"><table role="presentation" width="100%" cellpadding="0" cellspacing="0">
${rows.map((r, i) => card(r, i + 1)).join('')}
</table></td></tr>
<tr><td style="padding:4px 28px 28px;font-size:12px;color:#9CA3AF;line-height:1.6">
  All ideas were also added to your content calendar in Google Sheets.<br>
  Data: <a href="https://apify.com/inter974/google-trends-api" style="color:#6B7280">Google Trends API</a> and <a href="https://apify.com/inter974/google-news-scraper" style="color:#6B7280">Google News Scraper</a> on Apify · Ideas: OpenAI
</td></tr></table></div>`;

const top = rows[0];
const subject = `${rows.length} content idea${rows.length > 1 ? 's' : ''} for this week` + (top ? ` - top pick: "${top['Target search']}" (${top['Search growth']})` : '');
return [{ json: { subject, html, ideas: rows.length } }];
